const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle',timeout:60000});
await page.locator('#start-button').click();
await page.waitForTimeout(1200);
await page.screenshot({path:'/tmp/opencode/afterglow-gameplay.jpg',type:'jpeg',quality:82});
console.log('mission visible:',await page.locator('#mission-panel').isVisible(),'distance:',await page.locator('#distance').textContent(),'errors:',JSON.stringify(errors));
await browser.close();
