import { createRequire } from 'node:module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle',timeout:60000});
await page.locator('#start-button').tap();
const controlsVisible=await page.locator('#touch-controls').evaluate(e=>getComputedStyle(e).display!=='none' && e.getBoundingClientRect().width>0);
const overflow=await page.evaluate(()=>({width:document.documentElement.scrollWidth,innerWidth, height:document.documentElement.scrollHeight,innerHeight}));
await page.locator('[data-drive="gas"]').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',isPrimary:true,button:0,buttons:1,clientX:340,clientY:790});
await page.waitForTimeout(1400);
const speed=await page.locator('#speed-value').textContent();
await page.locator('[data-drive="gas"]').dispatchEvent('pointerup',{pointerId:1,pointerType:'touch',isPrimary:true,button:0,buttons:0,clientX:340,clientY:790});
await page.screenshot({path:'/tmp/opencode/afterglow-mobile.jpg',type:'jpeg',quality:82});
console.log(JSON.stringify({title:await page.title(),controlsVisible,overflow,speed,errors},null,2));
await browser.close();
